) values
(
  'delivery-intelligence-the-sleep-company',
  'Delivery Intelligence | The Sleep Company',
  'https://thesleepcompany.in',
  'Ecommerce - Backend Architecture - Production Systems',
  'Delivery promises made dependable',
  $$A large ecommerce business needed one reliable source of truth for delivery estimates across products, warehouses, locations, couriers, holidays, manufacturing delays, stock status, and express-delivery rules.$$,
  $$A centralized delivery-estimation service combined operational data and business rules from courier, inventory, ecommerce, and warehouse systems, with caching, administrative data controls, version history, backup and restore, and automated alerts.$$,
  array[
    'Backend architecture',
    'API design',
    'Business-rule modelling',
    'External integrations',
    'Caching',
    'Production scaling',
    'Observability',
    'Long-term maintenance'
  ],
  '[{"value":"50%","label":"reduction in support calls"},{"value":"5x","label":"FRT improvement"},{"value":"₹5 crore","label":"annual cost savings"}]'::jsonb,
  true,
  $case_study{"schemaVersion":3,"background":{"type":"pcb-svg","bucket":"case-study-assets","objectPath":"delivery-intelligence-the-sleep-company/background.f9e6f6fcd6f7e4ef8bed.svg","lensObjectPath":"delivery-intelligence-the-sleep-company/background-lens.7b727273f724e113c135.svg","width":2400,"height":15343.2},"summary":"A scattered delivery-date calculation process was rebuilt as a centralized EDD service that could support ecommerce touchpoints, logistics operations, warehouse data, product rules, courier timelines, stock states, holidays, and manufacturing delays from one dependable source of truth.","role":"Backend lead: Architecture, API design, integrations, infrastructure, production support, complete technical ownership.","sections":[{"id":"outcome-snapshot","type":"outcome-table","tone":"muted","eyebrow":"Outcome snapshot","title":"Delivery accuracy, support load, and response speed moved together.","rows":[{"metric":"Delivery-date accuracy","before":"30%","after":"95%","impact":"~2x accuracy increase"},{"metric":"Daily support calls","before":"500","after":"250","impact":"50% reduction"},{"metric":"FRT","before":"10%","after":"60%","impact":"5x improvement"}],"footer":{"value":"₹5 crore","label":"annual cost savings","detail":"Lower support volume and faster first-response handling turned the operational gains into measurable recurring savings."}},{"id":"operating-model-shift","type":"comparison","tone":"base","eyebrow":"Operating model shift","title":"From fragmented delivery promises to one controlled source of truth.","beforeLabel":"Before","afterLabel":"After","items":[{"before":"Delivery estimates split across frontend logic, team-owned sheets, and disconnected databases.","after":"One backend EDD API serving ecommerce, logistics, warehouse, and operational touchpoints."},{"before":"Important variables handled inconsistently: stock state, holidays, manufacturing delay, courier timing, and warehouse location.","after":"A single calculation path combined product, courier, warehouse, order, holiday, stock, and cutoff data."},{"before":"Manual correction loops created support pressure and low confidence in customer-facing promises.","after":"Controlled upload workflows, validation reports, snapshots, restores, and alerts gave operations a safer way to manage EDD data."}]},{"id":"system-flow","type":"system-flow","tone":"muted","eyebrow":"System flow","title":"Scattered delivery data became one controlled delivery-date API.","items":[{"step":"01","title":"Normalize scattered inputs","detail":"Product, warehouse, courier, order, holiday, stock, and manufacturing-delay data were brought into one calculation path.","stat":"8","statLabel":"data domains"},{"step":"02","title":"Control operational changes","detail":"Admin updates moved through validation, correction sheets, snapshots, restores, and cache refreshes before affecting live promises.","stat":"7","statLabel":"control workflows"},{"step":"03","title":"Serve one EDD API","detail":"A NestJS service read operational records from MongoDB and served high-read delivery rules through Redis-backed paths.","stat":"3","statLabel":"runtime layers"}]},{"id":"operational-control","type":"workflow","tone":"base","eyebrow":"Operational control","title":"Data changes became validated, reversible, and cache-aware.","intro":"Operations could update the rules behind customer-facing promises without scattered sheets, unsafe replacements, or unclear failures.","steps":["Upload","Validate","Correction sheet","Snapshot","Replace","Refresh cache","Alert"],"cards":[{"title":"Validated uploads","detail":"CSV/XLSX files were checked row by row before operational data could replace active collections.","keywords":["CSV/XLSX","row-level errors","admin workflow"]},{"title":"Snapshot-backed restores","detail":"Every upload and restore preserved the current collection first, keeping rollback paths available.","keywords":["snapshot","restore","MongoDB"]},{"title":"Operational alerts","detail":"Kubernetes-backed checks surfaced variant stock changes and admin-dashboard alerts.","keywords":["cron checks","stock state","alerts"]}]},{"id":"engineering-decisions","type":"evidence-grid","tone":"muted","eyebrow":"Engineering decisions","title":"Choices shaped around central dependency risk and production traffic.","cards":[{"title":"Isolated EDD service","detail":"Delivery logic could evolve in one backend system instead of being duplicated across touchpoints.","keywords":["NestJS","single API","service boundary"]},{"title":"Redis-backed read path","detail":"High-read rules such as holidays, processing times, cutoff hours, and variant delays were cached and refreshed after database changes.","keywords":["Redis","cache refresh","high-read data"]},{"title":"Lifecycle-aware delay logic","detail":"Holiday and Sunday handling accounted for where delay happened: factory, warehouse, courier, or post-dispatch.","keywords":["holidays","cutoffs","delay rules"]},{"title":"Seasonal traffic headroom","detail":"The deployment was designed to handle seasonal bursts without losing the central EDD dependency.","keywords":["Kubernetes","Diwali","scaling"]}]},{"id":"production-proof","type":"evidence-grid","tone":"base","eyebrow":"Production proof","title":"The system held up where production systems usually break.","cards":[{"title":"Seasonal traffic headroom","detail":"The central EDD service stayed dependable during Diwali demand, supporting 1.45M period requests and traffic roughly 199% above the previous month.","keywords":["1.45M requests","199% traffic lift","Kubernetes scaling"]},{"title":"Cache-safe rule updates","detail":"High-read delivery rules were served through Redis and refreshed after database changes, so admin updates did not leave stale promises in circulation.","keywords":["Redis","cache refresh","high-read rules"]},{"title":"Rollback-ready operations","detail":"Uploads validated rows before replacement and snapshotted active collections first, giving operations a controlled recovery path for delivery data changes.","keywords":["row validation","snapshots","restore path"]},{"title":"Production visibility","detail":"SigNoz brought EDD logs and traces into one searchable view, with alerts surfacing downtime, slow P90 responses, and elevated error rates before delivery promises degraded.","keywords":["SigNoz","P90 monitoring","error alerts"]}],"circuitAnchor":"section-bottom"},{"id":"communication-automation","type":"impact-highlight","tone":"base","eyebrow":"Additional impact","title":"Customer communication rebuilt around the full order journey.","detail":"A separate notification-system overhaul was built to keep customers properly informed throughout the entire order journey—from order placement through processing, dispatch, delivery, cancellation, and returns. The system relied heavily on EDD as the foundation for timely, journey-aware communication.","capabilities":["Notification-system architecture","Order-journey communication","Event integrations","Technical ownership"],"metrics":[{"value":"35%","label":"reduction in support calls"},{"value":"₹3 crore","label":"annual support-cost savings"},{"value":"30+","label":"new notifications introduced"}],"circuitAnchor":"section-bottom"},{"id":"capabilities-demonstrated","type":"capability-band","tone":"muted","eyebrow":"Capabilities demonstrated","title":"Backend architecture carried through production ownership.","showProjectCapabilities":true,"primaryActionLabel":"Discuss a Project","secondaryActionLabel":"Visit Live Site"}],"heroVisual":{"type":"edd-calculation","eyebrow":"Request to promise","title":"One request, resolved into a dependable promise.","description":"A delivery estimate request follows a curved path through destination resolution, fulfilment source, dispatch readiness, and promise assembly. EasyEcom supplies warehouse data. ClickPost supplies courier and delivery-promise data before the service returns dispatch, delivery-range, and express-availability values.","requestLabel":"EDD request","requestFields":[{"label":"Product","value":"Product ID"},{"label":"Destination","value":"Pincode"},{"label":"Requested","value":"Date + time"}],"integrations":[{"key":"clickpost","name":"ClickPost","role":"Courier API"},{"key":"easyecom","name":"EasyEcom","role":"Warehouse API"}],"stages":[{"number":"01","title":"Destination resolution","items":[{"label":"Pincode serviceability"},{"label":"Recommended courier partner","sourceKey":"clickpost"},{"label":"Available delivery modes"}]},{"number":"02","title":"Fulfilment source","items":[{"label":"Inventory availability"},{"label":"Warehouse determination","sourceKey":"easyecom"},{"label":"Warehouse details","sourceKey":"easyecom"}]},{"number":"03","title":"Dispatch readiness","items":[{"label":"Processing time"},{"label":"Manufacturing delay"},{"label":"Cutoff + holiday calendar"}]},{"number":"04","title":"Promise assembly","items":[{"label":"Baseline post-dispatch range","sourceKey":"clickpost"},{"label":"Express eligibility","sourceKey":"clickpost"},{"label":"Final delivery range"}]}],"responseLabel":"EDD response","responseFields":[{"label":"Dispatch","value":"Dispatch date"},{"label":"Delivery","value":"Date range"},{"label":"Express","value":"Available / unavailable"}],"layout":{"breakpoints":{"compactMax":480,"mobileMax":800,"tabletMax":1080},"canvas":{"width":1440,"height":810,"frameInset":1,"gridSize":28},"desktop":{"boundary":{"x":320,"y":130,"width":800,"height":535},"request":{"x":24,"y":260,"width":190,"height":280},"response":{"x":1226,"y":260,"width":190,"height":280},"stageSize":{"width":216,"height":185},"stagePositions":[{"x":353,"y":180},{"x":526,"y":430},{"x":699,"y":180},{"x":872,"y":430}],"flowPaths":["M226 400 C254 400 280 400 308 400","M461 377 V423 C461 452 482 475 502 475 H514","M634 418 V372 C634 343 655 325 675 325 H687","M807 377 V423 C807 452 828 475 848 475 H860","M1132 400 C1160 400 1186 400 1214 400"],"services":[{"integrationKey":"clickpost","x":900,"y":25,"width":200,"height":70,"path":"M900 60 C850 60 800 80 800 118"},{"integrationKey":"easyecom","x":340,"y":715,"width":200,"height":70,"path":"M540 750 C590 750 650 720 650 677"}]},"tablet":{"boundary":{"x":316,"y":130,"width":808,"height":535},"request":{"x":24,"y":260,"width":202,"height":280},"response":{"x":1214,"y":260,"width":202,"height":280},"stageSize":{"width":236,"height":185},"stagePositions":[{"x":347,"y":180},{"x":520,"y":430},{"x":693,"y":180},{"x":866,"y":430}],"flowPaths":["M238 400 C260 400 282 400 304 400","M461 377 V423 C461 452 482 475 508 475","M634 418 V372 C634 343 655 325 681 325","M807 377 V423 C807 452 828 475 854 475","M1136 400 C1158 400 1180 400 1202 400"],"services":[{"integrationKey":"clickpost","x":888,"y":25,"width":224,"height":70,"path":"M888 60 C844 60 800 80 800 118"},{"integrationKey":"easyecom","x":316,"y":715,"width":224,"height":70,"path":"M540 750 C590 750 650 720 650 677"}]},"mobile":{"groupLabel":"Promise engine","canvasPadding":32,"compactCanvasPadding":18,"endpointPadding":22,"compactEndpointPadding":18,"enginePadding":20,"compactEnginePadding":18,"entryColumns":[37.5,25,37.5],"entryPaddingTop":28,"entryPaddingBottom":38,"integrationPadding":12,"compactIntegrationPadding":10,"integrationConnectorHeight":36,"integrationConnectorGap":4,"responseConnectorHeight":34,"stageGap":26,"stagePadding":20,"compactStagePadding":18,"compactStageHeaderPadding":15,"compactFieldRows":{"labelMinWidth":82,"labelFraction":0.42,"valueFraction":1,"gap":12,"paddingBlock":13},"stageColumns":{"titleMinWidth":108,"titleFraction":0.55,"detailsFraction":1.45,"gap":22,"compactGap":16},"integrationPositions":[{"integrationKey":"clickpost","column":1},{"integrationKey":"easyecom","column":3}],"connections":[{"from":"request","to":"engine","kind":"primary"},{"from":"clickpost","to":"engine","kind":"api"},{"from":"easyecom","to":"engine","kind":"api"},{"from":"engine","to":"response","kind":"primary"}]}}}}$case_study$::jsonb,
  1,
  'published'
),
(
  'leads-management-the-sleep-company',
  'Leads Management | The Sleep Company',
  'https://thesleepcompany.in',
  'Ecommerce - Integrations - High-Volume Systems',
  'Fragmented lead capture, rebuilt as one dependable system',
  $$Lead capture relied on spreadsheets and disconnected systems. The business needed a centralized platform for collecting lead activities, retaining owned records, enriching applicable data, and synchronizing it across marketing, sales, and analytics systems.$$,
  $$A centralized lead service replaced spreadsheet-based middleware, retained owned lead-activity records, normalized payloads for downstream systems, enriched applicable activities through a nearest-store API, and handled custom activity-type workflows.$$,
  array[
    'System integration',
    'Backend architecture',
    'Business workflows',
    'Data enrichment',
    'Workflow orchestration',
    'Cloud deployment',
    'Scaling',
    'Production support'
  ],
  '[{"value":"2.2x","label":"daily activity volume growth"},{"value":"626K","label":"monthly activities sustained"},{"value":"3.6M","label":"requests in 30 days"}]'::jsonb,
  true,
  $case_study{"schemaVersion":3,"background":{"type":"pcb-svg","bucket":"case-study-assets","objectPath":"leads-management-the-sleep-company/background.9903f7dfb3275f2d9bb9.svg","lensObjectPath":"leads-management-the-sleep-company/background-lens.5de537a82a21de0fe3fc.svg","width":2400,"height":14322.5},"summary":"80+ website and store-management touchpoints depended on Google Sheets workflows that dropped over half of incoming lead activities. One owned lead service replaced that fragile handoff with consistent processing, durable activity records, custom activity-type workflows, downstream synchronization, and production recovery.","role":"Backend lead: Architecture, API design, integrations, infrastructure, production support, complete technical ownership.","heroVisual":{"type":"lead-network","eyebrow":"Touchpoint to owned record","title":"Many lead-activity sources, one controlled processing path.","description":"Website, store, and webhook activity converges into one Lead Service before owned storage and downstream delivery.","sourceLabel":"Capture surface","sourceStat":"80+","sourceStatLabel":"touchpoints","sources":[{"key":"website","name":"Website journeys","role":"Forms + product flows"},{"key":"stores","name":"Store platforms","role":"Assisted activity capture"},{"key":"webhooks","name":"Inbound webhooks","role":"JustDial + LeadSquared"}],"serviceLabel":"Lead Service","serviceRole":"Owned processing boundary","stages":[{"number":"01","title":"Capture","detail":"Phone + activity type"},{"number":"02","title":"Normalize","detail":"Shared field mapping"},{"number":"03","title":"Enrich","detail":"Nearest-store lookup"},{"number":"04","title":"Process","detail":"Custom activity workflows"}],"record":{"name":"MongoDB","role":"Owned database","detail":"Source activity + downstream task states"},"destinationLabel":"Downstream systems","destinations":[{"key":"leadsquared","name":"LeadSquared","role":"CRM + activities"},{"key":"webengage","name":"WebEngage","role":"Customer engagement"},{"key":"bigquery","name":"BigQuery","role":"Lead analytics"}],"layout":{"breakpoints":{"compactMax":650,"mobileMax":800,"tabletMax":1080},"canvas":{"width":1240,"height":620,"frameInset":1,"gridSize":28},"wide":{"sourceX":26,"destinationX":930,"laneWidth":284,"titleY":45,"statY":84,"sourceRuleY":100,"destinationRuleY":64,"nodeStartY":178,"nodeGap":93,"nodeWidth":284,"nodeHeight":79,"nodeTextX":17,"nodeTitleY":32,"nodeDetailY":57,"nodeAccentStartX":16,"nodeAccentEndX":40,"core":{"x":395,"y":26,"width":450,"height":568},"sourceConnectorPath":"M322 310H383","destinationConnectorPath":"M857 310H918"}}},"sections":[{"id":"outcome-snapshot","tone":"muted","eyebrow":"Outcome snapshot","title":"Lead-activity capture became dependable enough to support business growth.","type":"outcome-table","rows":[{"metric":"Lead-activity capture","before":"Less than 50%","after":"~99.5%","impact":"Nearly complete capture"},{"metric":"Monthly lead activities","before":"177,080 · Nov 2024","after":"410,087 · Jan 2025","impact":"~2.2x daily activity volume"},{"metric":"Lead-activity data operations","before":"Manual reconciliation","after":"Owned records + analytics","impact":"Almost all gathering work removed"}],"footer":{"value":"≈70%","label":"of revenue influenced by lead journeys","detail":"Dependable capture protected a commercially important acquisition channel instead of leaving it constrained by spreadsheet throughput."}},{"id":"operating-model-shift","tone":"base","eyebrow":"Operating model shift","title":"From spreadsheet transport to owned lead infrastructure.","type":"comparison","beforeLabel":"Before","afterLabel":"After","items":[{"before":"Google Sheets workflows dropped more than half of incoming lead activities under production volume.","after":"One NestJS service received lead activities from website, store, and webhook touchpoints."},{"before":"The business had no owned lead-activity database and depended on downstream tools for visibility.","after":"MongoDB retained activity payloads and downstream processing states in one controlled record."},{"before":"Analytics and propagation required manual searching across disconnected sources.","after":"LeadSquared, WebEngage, and BigQuery received data through one observable workflow."}]},{"id":"system-flow","tone":"muted","eyebrow":"System flow","title":"Every lead activity entered one owned processing path.","type":"system-flow","items":[{"step":"01","title":"Accept valuable data","detail":"Loose validation preserved incomplete lead activities instead of rejecting them before the business could act.","stat":"2","statLabel":"required fields"},{"step":"02","title":"Normalize by type","detail":"Shared mappings handled the common path while custom activities and source payloads used bounded type-specific processing.","stat":"80+","statLabel":"touchpoints"},{"step":"03","title":"Persist and distribute","detail":"The owned activity record kept the source payload and task states before data moved into sales, engagement, and analytics systems.","stat":"3","statLabel":"downstream systems"}]},{"id":"workflow-control","tone":"base","eyebrow":"Workflow control","title":"Failed downstream work remained visible and recoverable.","type":"workflow","intro":"Separate task states and a bounded retry window turned partial downstream failures into routine recovery work instead of silently lost lead activities.","steps":["Receive","Validate essentials","Map + enrich","Persist","Propagate","Record status","Retry failures"],"cards":[{"title":"Separate task states","detail":"LeadSquared, WebEngage, BigQuery, and other tasks retained independent success or failure fields.","keywords":["targeted recovery","task status","owned record"]},{"title":"Three-day retry window","detail":"A daily Kubernetes cron inspected recent records and repeated only the downstream work that remained incomplete.","keywords":["daily cron","bounded replay","failure recovery"]},{"title":"Operational visibility","detail":"Teams could inspect central records and analytics directly while routine recovery stayed automated.","keywords":["MongoDB","BigQuery","less manual work"]}]},{"id":"engineering-decisions","tone":"muted","eyebrow":"Engineering decisions","title":"The architecture protected capture without overengineering the first release.","type":"evidence-grid","cards":[{"title":"Preserve first","detail":"MongoDB retained structured and loosely structured fields so newly introduced payload data was not discarded while mappings evolved.","keywords":["MongoDB","evolving payloads","field retention"]},{"title":"Permissive validation","detail":"Only phone number and activity type were mandatory because incomplete activity data could still have commercial value.","keywords":["business value","loose schema","capture first"]},{"title":"Custom type workflows","detail":"Common lead activities reused one mapping path; LeadSquared custom activities and source exceptions used explicit type-based processing.","keywords":["shared mapping","custom activities","bounded exceptions"]},{"title":"Open, rate-limited API","detail":"The ingestion boundary stayed open for distributed business touchpoints while IP-based limits constrained abuse.","keywords":["IP rate limits","open ingestion","touchpoint access"]}]},{"id":"production-proof","tone":"base","eyebrow":"Production proof","title":"The system handled sales traffic—and improved when an assumption failed.","type":"evidence-grid","cards":[{"title":"626,470 lead activities","detail":"The owned service sustained more than 626K lead-activity records in a measured 30-day period.","keywords":["30 days","owned records","production scale"]},{"title":"3,611,900 requests","detail":"Webhook-heavy traffic was sustained in the same period; repeated LeadSquared activity callbacks accounted for most requests.","keywords":["webhook traffic","contextual metric","LeadSquared"]},{"title":"Scaling assumptions corrected","detail":"A 75% trigger and 60-second scale-down window caused spike intolerance. The policy moved to 60% CPU with a 300-second stabilization window.","keywords":["2–10 pods","60% CPU","300s stabilization"]},{"title":"Observable by design","detail":"SigNoz exposed searchable logs and traces with alerts for downtime, P90 degradation, elevated 500s, and elevated 400s.","keywords":["SigNoz","P90","logs + traces"]}],"circuitAnchor":"section-bottom"},{"id":"capabilities-demonstrated","tone":"muted","eyebrow":"Capabilities demonstrated","title":"Lead infrastructure carried through production ownership.","type":"capability-band","showProjectCapabilities":true,"primaryActionLabel":"Discuss a Project","secondaryActionLabel":"Visit Live Site"}]}$case_study$::jsonb,
  2,
  'published'
),
(
  'horecah',
  'Horecah',
  'https://horecah.com',
  'Freelance - Cross-Platform - Payments and Notifications',
  'Payments and notification journeys across web, Android, and iOS',
  $$A new hospitality hiring product needed two release-critical capabilities to behave consistently across three client platforms.$$,
  $$End-to-end Razorpay payments and event-driven push notifications were delivered through one React and Capacitor application, including backend verification, platform delivery, and deep-link routing.$$,
  array[
    'Cross-platform feature delivery',
    'Payment integration',
    'Push notifications',
    'Backend APIs',
    'Hasura events',
    'Deep linking',
    'Third-party package adaptation',
    'Production testing'
  ],
  '[{"value":"1","label":"shared client"},{"value":"2","label":"production features"},{"value":"3","label":"client platforms"}]'::jsonb,
  true,
  $case_study{"schemaVersion":3,"background":{"type":"pcb-svg","bucket":"case-study-assets","objectPath":"horecah/background.d0e81f816d967c5feb8d.svg","lensObjectPath":"horecah/background-lens.abbd807dc159ff4a775d.svg","width":2400,"height":11136},"summary":"Horecah's first release needed payments and transactional notifications to work as complete product journeys across web, Android, and iOS. During a one-month freelance engagement, both capabilities were delivered end to end through the shared React and Capacitor application, its Node.js backend, and Hasura-backed PostgreSQL data layer.","role":"Freelance feature engineer: End-to-end ownership of Razorpay payments and push notifications across web, Android, and iOS.","heroVisual":{"type":"cross-platform-features","eyebrow":"Contribution boundary","title":"One shared client, two owned features, three production platforms.","description":"Web, Android, and iOS share one React and Capacitor client that branches into the two end-to-end feature boundaries owned during the engagement: Razorpay payments and event-driven notification journeys.","platforms":["Web","Android","iOS"],"sharedCore":{"name":"React + Capacitor","role":"One shared client application"},"features":[{"key":"payments","name":"Razorpay payments","role":"End-to-end payment boundary","steps":["Backend order creation","Cross-platform Razorpay checkout","Signature verification + webhooks"]},{"key":"notifications","name":"Push notifications","role":"Automatic product journeys","steps":["Hasura event trigger","FCM / APNs delivery","Destination-aware deep-link routing"]}],"layout":{"breakpoints":{"stackMax":650,"fullCoreMax":1080}}},"sections":[{"id":"feature-scope","tone":"muted","eyebrow":"Feature scope","title":"Two product capabilities, completed across three client platforms.","type":"system-flow","items":[{"step":"01","title":"Create and launch checkout","detail":"The Node.js backend created Razorpay orders while one React and Capacitor checkout contract served web, Android, and iOS.","stat":"3","statLabel":"client platforms"},{"step":"02","title":"Verify independently","detail":"Backend signature verification supported the live checkout result; Razorpay webhooks preserved verification when the client flow stopped.","stat":"2","statLabel":"verification paths"},{"step":"03","title":"Complete the journey","detail":"Hasura events triggered notifications through FCM or APNs, with route data that opened the correct React screen after a tap.","stat":"1","statLabel":"routing contract"}]},{"id":"payment-integration","tone":"base","eyebrow":"Payment integration","title":"The shared payment flow required repairing the plugin boundary.","type":"evidence-grid","cards":[{"title":"Production-ready Capacitor fork","detail":"Razorpay's official Capacitor plugin did not integrate cleanly with the production setup. Its TypeScript toolchain, bundle format, checkout types, package identity, distributable build, and CocoaPods identity were adapted in a maintained Horecah fork.","keywords":["Capacitor 6","TypeScript","CocoaPods"]},{"title":"One implementation across clients","detail":"The repaired package kept web and native checkout behind one application-level contract instead of creating separate payment implementations for each platform.","keywords":["shared contract","web + native","Razorpay"]},{"title":"Two failure boundaries","detail":"Checkout responses were verified on the backend for immediate completion, while server-to-server webhooks reconciled payment state independently of the active client.","keywords":["signature verification","webhooks","reconciliation"]}]},{"id":"notification-delivery","tone":"muted","eyebrow":"Notification delivery","title":"A notification only worked when it returned the user to the right journey.","type":"evidence-grid","cards":[{"title":"Event-driven delivery","detail":"Hasura events connected product activity to automatic notification journeys instead of requiring manual sends.","keywords":["Hasura events","automatic triggers","PostgreSQL"]},{"title":"Platform-aware routing","detail":"The backend stored device tokens and selected FCM or APNs delivery according to the registered client platform.","keywords":["device tokens","FCM","APNs"]},{"title":"Consistent deep links","detail":"A shared payload structure carried the destination data needed for notification taps to open the intended React screen consistently on web, Android, and iOS.","keywords":["payload contract","deep links","cross-platform"]},{"title":"Web push restored","detail":"An initial web-push integration failure was diagnosed and resolved as part of bringing the complete notification path to release readiness.","keywords":["web push","integration debugging","release path"]}]},{"id":"production-readiness","tone":"base","eyebrow":"Production readiness","title":"Both features shipped with Horecah's first production release.","type":"evidence-grid","cards":[{"title":"Real-platform verification","detail":"Payments and notifications were exercised in web browsers and on physical Android and iOS devices, including foreground, background, and terminated application states.","keywords":["real devices","browser checks","app lifecycle"]},{"title":"Failure paths covered","detail":"Cancelled and failed payments, invalid verification, expired device tokens, and unsuccessful notification delivery were handled as part of the feature boundary.","keywords":["error handling","token lifecycle","payment failures"]},{"title":"Production v1 launch","detail":"The payment gateway and automated notification journeys launched with the complete first version of the product.","keywords":["v1 launch","payments","production ready"]}],"circuitAnchor":"section-bottom"},{"id":"capabilities-demonstrated","tone":"muted","eyebrow":"Capabilities demonstrated","title":"Cross-platform features carried through their complete production boundary.","type":"capability-band","showProjectCapabilities":true,"primaryActionLabel":"Discuss a Project","secondaryActionLabel":"Visit Live Site"}]}$case_study$::jsonb,
  3,
  'published'
)
on conflict (slug) do update set
  name = excluded.name,
  url = excluded.url,
  category = excluded.category,
  title = excluded.title,
  challenge = excluded.challenge,
  delivery = excluded.delivery,
  capabilities = excluded.capabilities,
  metrics = excluded.metrics,
  has_case_study = excluded.has_case_study,
  case_study_document = excluded.case_study_document,
  order_index = excluded.order_index,
  status = excluded.status;

update public.projects
set case_study_document = jsonb_set(
  case_study_document,
  '{role}',
  to_jsonb('Backend lead: Architecture, API design, integrations, infrastructure, production support, complete technical ownership.'::text),
  false
)
where slug = 'delivery-intelligence-the-sleep-company'
  and has_case_study = true
  and case_study_document is not null;

update public.projects
set case_study_document = jsonb_set(
  case_study_document,
  '{sections}',
  (
    select jsonb_agg(
      case
        when section ->> 'id' = 'feature-scope' then
          $feature_scope${"id":"feature-scope","tone":"muted","eyebrow":"Feature scope","title":"Two production features, delivered through one shared cross-platform client.","type":"evidence-grid","columns":3,"cards":[{"title":"Shared client foundation","detail":"One React and Capacitor application carried the common client contracts and platform configuration across web, Android, and iOS.","keywords":["React + Capacitor","web + native","one client"]},{"title":"Payments, end to end","detail":"Ownership ran from backend order creation and Razorpay checkout through signature verification and independent webhook reconciliation.","keywords":["order creation","checkout","verification"]},{"title":"Notifications, event to destination","detail":"Ownership ran from Hasura-triggered product events through FCM or APNs delivery and destination-aware navigation after a tap.","keywords":["Hasura events","FCM + APNs","deep linking"]}]}$feature_scope$::jsonb
        else section
      end
      order by ordinal
    )
    from jsonb_array_elements(case_study_document -> 'sections')
      with ordinality as case_sections(section, ordinal)
  ),
  false
)
where slug = 'horecah'
  and has_case_study = true
  and case_study_document is not null;
